    children: () => {
      const card = _cardTmpl.clone();
      bindText(card.refs.name, () => selected.value?.name ?? '');
      bindText(card.refs.email, () => selected.value?.email ?? '');
      return card;
    },
    fallback: () => template('<p>Select a contact</p>')()
