import { signal, batch, effect } from '@samrey/reactivity';
export function createHighFrequencyUpdater() {
  const x = signal(0);
  const y = signal(0);
  const z = signal(0);
  let effectFiredCount = 0;
  effect(() => {
    // Read all three
    x.value; y.value; z.value;
    effectFiredCount++;
  });
  return {
    x, y, z,
    getEffectFiredCount: () => effectFiredCount,
    updateAll: (newX: number, newY: number, newZ: number) => {
      batch(() => {
        x.value = newX;
        y.value = newY;
        z.value = newZ;
      });
    }
  };
}

